// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function _depositCreditsExact(uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt >= c.MinDeposit());
        vm.assume(address(this).balance >= amt);
        try c.Deposit{value: amt}() {} catch { return; }
        assertTrue(c.balances(address(this)) == amt);
    }

    function testFuzz_depositCreditsExact(uint256 amt) public {
        _depositCreditsExact(amt);
    }

    receive() external payable {}
}
